"""Original ARDS strategy, airway and obstructive ventilation questions."""
from create_critical_ventilator_mechanics import rows,q,PV,AR,ES,ref
NM=ref('SCCM neuromuscular blockade in ARDS guideline: 2026','https://www.sccm.org/clinical-resources/guidelines/guidelines/guidelines-for-the-administration-of-neuromuscular-blockade')

q('A ventilated ARDS patient remains at P/F 110 after stabilization with low tidal volume and adjusted PEEP. Which intervention has mortality benefit when appropriately applied?', 'Early prolonged prone positioning, commonly at least 16 hours per session',[
 ('Brief five-minute proning only for suctioning','This does not reproduce the prolonged-session evidence.'),('Routine high tidal volume to normalize oxygenation rapidly','This increases ventilator-induced injury risk.'),('Routine prolonged high-pressure recruitment maneuvers','These can cause harm and are not the preferred evidence-based intervention.')],
 'Proning is more than an oxygenation rescue maneuver','**Prolonged prone positioning benefits appropriately selected moderate/severe ARDS.**',['ESICM recommends early sessions of at least sixteen hours when P/F remains below 150 after stabilization.','Use trained teams and protect the airway, lines, pressure points and eyes.'], '**Continue lung-protective ventilation while prone.**',['Assess contraindications and hemodynamic tolerance.','A temporary oxygenation response alone does not define every aspect of benefit.'],[['Selection','Persistent significant hypoxemia'],['Duration','Prolonged sessions'],['Safety','Team, airway and pressure protection']],[ES,AR],style='clinical_scenario')

q('What is the main physiological trade-off when increasing PEEP in ARDS?', 'Potential recruitment versus overdistension, increased RV load and hemodynamic compromise',[
 ('Guaranteed recruitment with no circulatory consequences','Recruitability differs and positive pressure can impair circulation.'),('Only improved CO2 clearance without any effect on oxygenation','PEEP has major effects on aeration and oxygenation as well as mechanics.'),('A direct reduction in all lung stress regardless of the lung phenotype','Overdistension can increase injury in poorly recruitable regions.')],
 'Choose PEEP by benefit and harm rather than one target number','**Higher PEEP can stabilize recruitable alveoli but harm other lung or cardiovascular compartments.**',['Assess oxygenation, compliance, driving pressure and circulation after changes.','RV pressure overload can worsen with excessive lung inflation.'], '**Reassess the response in the individual patient.**',['Higher PEEP without prolonged recruitment maneuvers is an ATS option in moderate-to-severe ARDS.','A better oxygen saturation does not automatically prove the whole intervention is beneficial.'],[['Recruitment','Potential benefit'],['Overdistension','Potential lung harm'],['RV/venous return','Potential circulatory harm']],[AR,ES])

q('Which recruitment strategy is recommended against routinely in moderate-to-severe ARDS?', 'Prolonged high-pressure lung recruitment maneuvers',[
 ('Low tidal volume ventilation','This remains a core protective strategy.'),('Early prolonged prone positioning in a suitable patient','This has evidence of benefit.'),('Assessment of PEEP and respiratory mechanics','This is important routine care.')],
 'A dramatic oxygenation maneuver can still have harmful outcomes','**ATS strongly recommends against prolonged recruitment maneuvers.**',['High intrathoracic pressure can cause hypotension, barotrauma and overdistension.','This does not mean all PEEP is harmful or that a disconnection event requires no reassessment.'], '**Use established protective strategies and appropriate rescue pathways.**',['Check tube/circuit, position and reversible causes before escalating support.','Consider expert referral for refractory severe ARDS.'],[['Protective VT','Core strategy'],['Proning','Selected established benefit'],['Prolonged high-pressure RM','Avoid routine use']],[AR,ES])

q('An ARDS patient has P/F 95 with persistent hypoxemia and dangerous dyssynchrony despite appropriate analgesia/sedation and ventilator adjustment. What does SCCM 2026 conditionally support?', 'Neuromuscular blockade as part of an individualized strategy',[
 ('Paralysis for every ventilated patient regardless of severity or interaction','The recommendation is not universal.'),('Paralysis as a substitute for analgesia and sedation','Neuromuscular blockers do not provide comfort, amnesia or pain relief.'),('Avoidance of neuromuscular blockade in every ARDS case','Selected patients unable to meet targets despite sedation may benefit.')],
 'Use paralysis to achieve a defined protective target','**SCCM conditionally suggests NMBAs for ARDS with P/F below 150 and persistent hypoxemia or unmet ventilation targets on sedation.**',['The recommendation has limited-certainty evidence and requires patient-specific assessment.','Proning by itself does not make paralysis mandatory in every patient.'], '**Maintain adequate analgesia/sedation and reassess ongoing need.**',['Protect eyes, skin, nerves and mobility.','Do not use an absent movement response as evidence of adequate sedation.'],[['Indication','Selected persistent failure to meet targets'],['NMBA','No analgesia/amnesia'],['Duration','Reassess and minimize unnecessary exposure']],[NM],style='clinical_scenario')

q('A passive ARDS patient has VT 8 mL/kg PBW and plateau pressure 34 cm H2O. Which initial ventilator adjustment is most appropriate?', 'Reduce tidal volume within the lung-protective range and reassess plateau and gas exchange',[
 ('Increase tidal volume to normalize PaCO2 regardless of plateau','This can worsen injurious stress.'),('Ignore plateau if pulse oximetry is normal','Oxygenation does not establish mechanical safety.'),('Use actual body weight to justify a larger tidal volume','PBW remains the relevant volume-sizing approach.')],
 'Limit tidal stretch and inspiratory pressure','**ARDS protection uses low PBW-based tidal volume and plateau-pressure assessment.**',['A starting six-mL/kg strategy is commonly adjusted within the protective range.','Gas-exchange targets may permit some hypercapnia when clinically tolerable.'], '**Check measurement validity and the chest-wall context.**',['A passive no-flow plateau is needed for interpretation.','Review rate, pH, auto-PEEP and effort rather than adjust one setting blindly.'],[['VT','Reduce excessive tidal exposure'],['Plateau','Reassess after adjustment'],['Gas exchange','Balance with protective constraints']],[AR,PV],style='clinical_scenario')

q('A severely obese ventilated patient has elevated plateau pressure. Which distinction matters before equating this with excessive lung distending pressure?', 'Airway pressure includes chest-wall as well as lung elastic load',[
 ('Airway plateau always equals transpulmonary pressure','Pleural/chest-wall pressure contributes to the airway value.'),('Obesity makes all high airway pressures harmless','Lung injury can still occur and protection remains necessary.'),('Esophageal pressure is irrelevant to any assessment of transpulmonary mechanics','It can inform selected expert assessments, with limitations.')],
 'Respiratory-system pressure is not identical to lung pressure','**A stiff chest wall can raise airway plateau without the same increase in transpulmonary pressure.**',['This does not justify unrestricted volume or pressure.','Position, abdominal load, effort and measurement quality affect interpretation.'], '**Use a complete mechanics and gas-exchange assessment.**',['Consider specialized measurements when the clinical question warrants them.','Reassess PEEP, recruitability and circulation.'],[['Airway pressure','Lung plus chest-wall load'],['Transpulmonary pressure','Airway minus pleural estimate'],['Obesity','Changes mechanics, not a safety exemption']],[PV],style='clinical_scenario')

q('A ventilated severe asthma patient becomes profoundly hypotensive with marked dynamic hyperinflation and no evidence of tension pneumothorax. Which immediate maneuver can be helpful while definitive ventilator changes are made?', 'Briefly disconnect the ventilator to allow prolonged exhalation',[
 ('Increase respiratory rate to wash out CO2 faster','This can worsen trapped gas.'),('Give repeated manual rapid large breaths','This can further increase hyperinflation.'),('Increase tidal volume as the first response','This can worsen overdistension and hemodynamic compromise.')],
 'Severe trapping can create obstructive circulatory failure','**Brief disconnection can reveal and temporarily relieve hyperinflation-related hypotension.**',['Continue assessment for pneumothorax, obstruction and other causes.','The maneuver is a bridge, not a durable ventilator plan.'], '**Reduce excessive minute ventilation and lengthen exhalation.**',['Treat bronchospasm and airway obstruction.','Accept appropriate permissive hypercapnia rather than chase normal CO2 at the cost of dangerous pressure.'],[['Trapped gas','Raises intrathoracic pressure'],['Disconnection','Temporary exhalation relief'],['Definitive changes','More expiratory time and less excessive ventilation']],[PV,ref('Mechanical ventilation in severe asthma: physiological management','https://pmc.ncbi.nlm.nih.gov/articles/PMC1414026/')],style='clinical_scenario')

q('Which ventilator strategy is generally appropriate in severe airflow obstruction with gas trapping?', 'Reduce excessive respiratory rate and provide sufficient expiratory time',[
 ('Increase rate aggressively to normalize PaCO2 immediately','This shortens exhalation and can worsen trapping.'),('Use larger tidal volumes to overcome all resistance','This can increase hyperinflation and pressure.'),('Shorten expiration by prolonging inspiratory time in every patient','This is counterproductive when incomplete exhalation is the main problem.')],
 'Prioritize safe emptying over a normal CO2 number','**Expiratory flow limitation makes time for exhalation essential.**',['Higher inspiratory flow in volume control can shorten inspiratory time and lengthen expiration.','Monitor plateau, intrinsic PEEP, pH and circulation.'], '**Treat the obstructive disease and reassess effort.**',['The safest rate and volume depend on the patient.','Permissive hypercapnia has important contraindications and requires pH/clinical review.'],[['Longer expiration','Reduces trapping'],['High rate/large VT','Can worsen hyperinflation'],['Monitoring','Pressures, pH and hemodynamics']],[PV,ref('Severe asthma ventilation review','https://pmc.ncbi.nlm.nih.gov/articles/PMC1414026/')])

q('A low-VT ARDS patient repeatedly double-triggers, receiving two consecutive breaths with little exhalation. Why is this important?', 'Breath stacking can deliver a much larger effective tidal volume than the set single-breath value',[
 ('The protective setting guarantees protection despite every interaction','Actual delivered breath pattern matters.'),('Double-triggering proves the patient is ready for extubation','High drive and dyssynchrony can occur in severe disease.'),('The only appropriate response is to increase VT without reviewing the cause','This may worsen injury and misses pain, drive and timing problems.')],
 'Protect the actual breath, not only the programmed number','**High drive or mismatched neural and mechanical inspiratory time can cause stacking.**',['Check pain, fever, acidosis, flow and timing.','Selected sedation or neuromuscular blockade may be needed when dangerous interaction persists despite correction.'], '**Assess delivered volumes and waveforms.**',['Adjust the mechanism rather than reflexively deepen every patient’s sedation.','Maintain the broader lung-protective and organ-support plan.'],[['Set VT','May underestimate stacked exposure'],['High drive/timing','Potential causes'],['Management','Correct reversible causes and interaction']],[PV,NM],style='clinical_scenario')

q('During volume-control ventilation, a patient makes strong inspiratory efforts and the pressure waveform becomes concave during inspiration. Which problem should be considered?', 'Inspiratory flow demand exceeding delivered flow',[
 ('An entirely passive patient with no unmet demand','The waveform and effort suggest interaction rather than passivity.'),('A definitive diagnosis of pneumothorax from waveform shape alone','Pneumothorax needs a different clinical assessment.'),('A mandatory indication to lower inspiratory flow further','This can worsen flow starvation.')],
 'The patient can demand more flow than a fixed delivery provides','**Flow starvation can produce an inspiratory pressure deflection and distress.**',['Assess drive, pain, acidosis and the set flow pattern.','Appropriate flow or mode adjustments may improve comfort and synchrony.'], '**Observe the patient while interpreting the screen.**',['Avoid treating every waveform change with sedation alone.','Reassess delivered volume, pressure and gas exchange after changes.'],[['Demand > flow','Potential dyssynchrony'],['Adjustment','Flow pattern/timing or mode'],['Safety','Continue lung protection']],[PV],style='clinical_scenario')

q('After an endotracheal tube is advanced, breath sounds disappear on the left while airway pressures rise. Which cause is most likely?', 'Right mainstem intubation',[
 ('A new bilateral pulmonary edema syndrome as the immediate consequence','The timing and unilateral ventilation change favor tube depth.'),('A primary metabolic acidosis','This does not explain unilateral breath-sound loss after tube movement.'),('An isolated rise in dead space without tube displacement','This does not best explain the direct temporal and anatomical pattern.')],
 'An airway-position change can create a one-lung problem','**The right main bronchus is a common site of inadvertent endobronchial placement.**',['Check tube depth and ventilation immediately.','Pneumothorax and obstruction remain alternatives if correction does not resolve the problem.'], '**Restore appropriate tube position and confirm it.**',['Use capnography plus clinical and imaging assessment as appropriate.','Capnography confirms tracheal gas exchange but does not alone exclude mainstem depth.'],[['Timing','After tube advancement'],['Finding','Unilateral ventilation'],['Action','Reassess and correct depth']],[PV],style='clinical_scenario')

q('A ventilated patient suddenly becomes hypoxemic and difficult to ventilate. Which approach is most appropriate?', 'Immediately assess displacement, obstruction, pneumothorax, equipment failure and other reversible causes while supporting oxygenation',[
 ('Increase FiO2 and wait without examining the patient or circuit','Oxygen alone does not correct an obstructed or displaced airway.'),('Assume every episode is worsening ARDS','Mechanical causes can be rapidly reversible and life-threatening.'),('Transport for CT before checking the airway and ventilator','This can delay essential bedside correction.')],
 'Use a structured bedside emergency assessment','**Abrupt deterioration should trigger airway, lung and circuit checks.**',['Manual ventilation with an appropriate bag can help distinguish equipment from patient problems while maintaining support.','Do not ignore hemodynamic causes or severe auto-PEEP.'], '**Treat the identified cause immediately.**',['Verify tube position/patency, inspect the circuit and examine the chest.','Use ultrasound or imaging when it helps without delaying urgent intervention.'],[['Airway','Displacement/obstruction'],['Lung','Pneumothorax/trapping or acute disease'],['Equipment','Circuit/ventilator failure']],[PV])

if __name__=='__main__':print(f'Mechanical ventilation cumulative draft: {len(rows)} questions')
